  (1, 'priya@studiopass.test', 'Barre Burn', 'Barre', 'Intermediate', 'Small, high-rep movements at the barre. Grip socks recommended.', 1, 50, 15, 2, '2026-10-20T14:00:00.000Z', 12, 'approved', 'Great fit for weekend mornings in Williamsburg.', 'admin@studiopass.test', '2026-10-15T19:00:00.000Z', '2026-10-13T15:00:00.000Z'),
  (2, 'sam@studiopass.test', 'Climb & Sprint Intervals', 'Spin', 'Advanced', 'Hill climbs and all-out sprints, built around power zones.', 4, 45, 16, 3, '2026-11-22T23:30:00.000Z', 6, 'pending', null, null, null, '2026-11-15T21:00:00.000Z'),
  (3, 'priya@studiopass.test', 'Prenatal Pilates', 'Pilates', 'Beginner', 'Safe, supportive Pilates for every trimester.', 2, 50, 10, 2, '2026-11-25T15:00:00.000Z', 8, 'pending', null, null, null, '2026-11-16T14:00:00.000Z'),
  (4, 'maya@studiopass.test', 'Yoga for Runners', 'Yoga', 'Intermediate', 'Hips, hamstrings and calves: mobility for people who run.', 1, 60, 14, 2, '2026-11-24T00:00:00.000Z', 4, 'pending', null, null, null, '2026-11-15T01:00:00.000Z'),
  (5, 'jordan@studiopass.test', 'Midnight Kettlebells', 'Strength', 'Advanced', 'Late-night kettlebell complexes.', 3, 45, 12, 2, '2026-11-21T04:00:00.000Z', 4, 'rejected', 'Chelsea closes at 10 pm. Could you propose a slot that ends by 9:30 pm?', 'admin@studiopass.test', '2026-11-12T19:00:00.000Z', '2026-11-11T03:00:00.000Z');
